  __ovr_denom = pop!(__overrides, "denom", nothing); isnothing(__ovr_denom) || push!(__eqs, denom ~ __ovr_denom)
  __ovr_denom__initial = pop!(__overrides, "denom__initial", nothing); isnothing(__ovr_denom__initial) || (__initial_conditions[denom] = __ovr_denom__initial)

  ### Constants
  __constants = Any[]

  ### Components

  ### Check there are no unmatched overrides
  isempty(__overrides) || throw(ArgumentError("overides: [$(join(keys(__overrides), ", "))] don't match names found in model. These names may exist in the model but could have been conditionally excluded."))

  ### Guesses

  ### Initialization Equations

  ### Assertions
  __assertions = []

  ### Equations
  push!(__eqs, sa ~ sin(alpha))
  push!(__eqs, ca ~ cos(alpha))
  push!(__eqs, sb ~ sin(beta))
  push!(__eqs, cb ~ cos(beta))
  push!(__eqs, st ~ sin(theta))
  push!(__eqs, ct ~ cos(theta))
  push!(__eqs, tt ~ tan(theta))
  push!(__eqs, sphi ~ sin(phi))
  push!(__eqs, cphi ~ cos(phi))
  push!(__eqs, spsi ~ sin(psi))
  push!(__eqs, cpsi ~ cos(psi))
  push!(__eqs, U ~ vt * ca * cb)
  push!(__eqs, V ~ vt * sb)
  push!(__eqs, W ~ vt * sa * cb)
  push!(__eqs, rho ~ 1.225 * (1 - 0.0065 * alt / 288.15) ^ 4.256)
  push!(__eqs, qbar ~ 0.5 * rho * vt * vt)
  push!(__eqs, Cx_tot ~ Cx0 + Cxa * alpha + Cxa2 * alpha * alpha + Cxde * el + Cxq * (cbar * Q / (2 * vt)))
  push!(__eqs, Cy_tot ~ Cy0 + Cyb * beta + Cyda * ail + Cydr * rud + Cyp * (B * P / (2 * vt)) + Cyr * (B * R / (2 * vt)))
  push!(__eqs, Cz_tot ~ Cz0 + Cza * alpha + Cza2 * alpha * alpha + Czde * el + Czq * (cbar * Q / (2 * vt)))
  push!(__eqs, Cl_tot ~ Cl0 + Clb * beta + Clda * ail + Cldr * rud + Clp * (B * P / (2 * vt)) + Clr * (B * R / (2 * vt)))
  push!(__eqs, Cm_tot ~ Cm0 + Cma * alpha + Cma2 * alpha * alpha + Cmde * el + Cmq * (cbar * Q / (2 * vt)))
  push!(__eqs, Cn_tot ~ Cn0 + Cnb * beta + Cnda * ail + Cndr * rud + Cnp * (B * P / (2 * vt)) + Cnr * (B * R / (2 * vt)))
  push!(__eqs, Udot ~ R * V - Q * W - g * st + qbar * S * Cx_tot / m + T / m)
  push!(__eqs, Vdot ~ P * W - R * U + g * ct * sphi + qbar * S * Cy_tot / m)
  push!(__eqs, Wdot ~ Q * U - P * V + g * ct * cphi + qbar * S * Cz_tot / m)
  push!(__eqs, L_tot ~ Cl_tot * qbar * S * B)
  push!(__eqs, M_tot ~ Cm_tot * qbar * S * cbar)
  push!(__eqs, N_tot ~ Cn_tot * qbar * S * B)
  push!(__eqs, denom ~ Jx * Jz - Jxz * Jxz)
  push!(__eqs, ModelingToolkit.D_nounits(vt) ~ (U * Udot + V * Vdot + W * Wdot) / vt)
  push!(__eqs, ModelingToolkit.D_nounits(alpha) ~ (U * Wdot - W * Udot) / (U * U + W * W))
  push!(__eqs, ModelingToolkit.D_nounits(beta) ~ (Vdot * vt - V * (U * Udot + V * Vdot + W * Wdot) / vt) / (vt * vt * cb))
  push!(__eqs, ModelingToolkit.D_nounits(P) ~ (Jz * L_tot + Jxz * N_tot - (Jz * (Jz - Jy) + Jxz * Jxz) * Q * R + Jxz * (Jx - Jy + Jz) * P * Q + Jxz * Q * Heng) / denom)
  push!(__eqs, ModelingToolkit.D_nounits(Q) ~ (M_tot + (Jz - Jx) * P * R - Jxz * (P * P - R * R) - R * Heng) / Jy)
  push!(__eqs, ModelingToolkit.D_nounits(R) ~ (Jx * N_tot + Jxz * L_tot + (Jx * (Jx - Jy) + Jxz * Jxz) * P * Q - Jxz * (Jx - Jy + Jz) * Q * R + Jx * Q * Heng) / denom)
  push!(__eqs, ModelingToolkit.D_nounits(npos) ~ U * (ct * cpsi) + V * (sphi * cpsi * st - cphi * spsi) + W * (cphi * st * cpsi + sphi * spsi))
  push!(__eqs, ModelingToolkit.D_nounits(epos) ~ U * (ct * spsi) + V * (sphi * spsi * st + cphi * cpsi) + W * (cphi * st * spsi - sphi * cpsi))
  push!(__eqs, ModelingToolkit.D_nounits(alt) ~ U * st - V * (sphi * ct) - W * (cphi * ct))
  push!(__eqs, ModelingToolkit.D_nounits(phi) ~ P + tt * (Q * sphi + R * cphi))
  push!(__eqs, ModelingToolkit.D_nounits(theta) ~ Q * cphi - R * sphi)
  push!(__eqs, ModelingToolkit.D_nounits(psi) ~ (Q * sphi + R * cphi) / ct)
  push!(__eqs, 0 ~ (U * Udot + V * Vdot + W * Wdot) / vt)
  push!(__eqs, 0 ~ (M_tot + (Jz - Jx) * P * R - Jxz * (P * P - R * R) - R * Heng) / Jy)

  # Return completely constructed System
  return System(__eqs, t, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
